FUNCTION handleDeleteAnimal(request, animal_id):
    // REQ-3-016; preconditions: existing non-deleted authorized animal and persistence available.
    REQUIRE authenticated animal client or admin OR RETURN 401 or 403. RETURN 404 for invalid or absent id.
    BEGIN TRANSACTION; lock animal, clinical records, and vaccinations. IF any record or vaccination references animal THEN ROLLBACK; RETURN 409. END IF
    MARK animal deleted; COMMIT; RETURN 204.
    // REQ-3-008. Repeat is 404; failure rollback preserves animal and every clinical relation.

FUNCTION handleDeleteClinicalRecord(request, record_id):
    // REQ-3-022; preconditions: existing record and persistence available.
    REQUIRE authenticated admin OR RETURN 401 or 403. RETURN 404 for non-positive or absent id.
    BEGIN TRANSACTION; lock record. IF status is FINAL THEN ROLLBACK; RETURN 409. END IF DELETE DRAFT record only; preserve animal and vaccinations; COMMIT; RETURN 204.
    // REQ-3-004. Repeat is 404; rollback leaves record and every relation unchanged.

FUNCTION handleGetAnimal(request, animal_id):
    // REQ-3-014; preconditions: persistence available.
    REQUIRE authenticated user or admin OR RETURN 401. IF animal_id is non-positive, absent, or deleted THEN RETURN 404. END IF
    REQUIRE caller owns animal or is admin under REQ-3-002 OR RETURN 403. RETURN 200 with animal.
    // Transaction: none; postcondition: state unchanged and errors have no persistent effect.

FUNCTION handleGetClinicalTimeline(request, animal_id):
    // REQ-3-028; preconditions: persistence available.
    REQUIRE authenticated animal client or admin OR RETURN 401 or 403. RETURN 404 for invalid or absent animal. REQUIRE admin for include_void true OR RETURN 403.
    VALIDATE inclusive event range, limit, and cursor where all three parts are supplied together and kind is RECORD or VACCINATION OR RETURN 400 or 422.
    READ records plus allowed vaccination events, sort by event_date, RECORD before VACCINATION, then id; apply cursor and RETURN 200 with next composite cursor.
    // Transaction: none; postcondition: all clinical records, vaccination rows, and relationships remain unchanged on success and error.

FUNCTION handleGetVaccinationStatus(request, animal_id):
    // REQ-3-027; preconditions: persistence available and explicit as_of date.
    REQUIRE authenticated animal client or admin OR RETURN 401 or 403. RETURN 404 for invalid or absent animal. VALIDATE as_of range and optional code enum OR RETURN 400 or 422.
    READ non-void vaccinations for animal and compute each requested status under REQ-3-009 using as_of; RETURN 200.
    // Transaction: none; postcondition: no vaccine, record, or animal is altered by computation or errors.

FUNCTION handleListClinicalRecords(request):
    // REQ-3-017; preconditions: persistence available.
    REQUIRE authenticated user or admin OR RETURN 401. VALIDATE ids, enums, code prefix, inclusive date range, and pagination OR RETURN 400 or 422.
    RETURN 404 for an unknown supplied animal. READ matching records for caller-owned animals when user, otherwise all matching records, ordered by id; RETURN 200 page.
    // Transaction: none; postcondition: clinical records, vaccinations, and animals are unchanged on success and errors.

FUNCTION handleGetHealth(request):
    // REQ-3-011; preconditions: none.
    IF local persistence probe fails THEN RETURN 503. END IF
    RETURN 200 with status ok.
    // Authorization: public. Transaction: none. Postcondition: persistent state remains unchanged; failure has no side effect.

FUNCTION handleListVaccinations(request):
    // REQ-3-023; preconditions: persistence available.
    REQUIRE authenticated user or admin OR RETURN 401. REQUIRE admin for include_void true OR RETURN 403. VALIDATE positive ids, vaccine enum, both inclusive date pairs, and pagination OR RETURN 400 or 422.
    RETURN 404 for unknown supplied animal. READ matching non-void caller-owned rows for user or requested admin rows, ordered by id; RETURN 200 page.
    // Transaction: none; all vaccination and clinical state stays unchanged on success and error.

FUNCTION handlePatchAnimal(request, animal_id):
    // REQ-3-015; preconditions: JSON request, existing non-deleted animal, and persistence available.
    REQUIRE authenticated animal client or admin OR RETURN 401 or 403. REQUIRE application/json OR RETURN 415. VALIDATE nonempty partial result under REQ-3-002 OR RETURN 400 or 422.
    BEGIN TRANSACTION; UPDATE supplied fields only; preserve clinical records and vaccinations; COMMIT; RETURN 200.
    // Identical valid payload is idempotent. Any persistence error rolls back and leaves all relations unchanged.

FUNCTION handlePatchClinicalRecord(request, record_id):
    // REQ-3-020; preconditions: JSON request, existing record, and persistence available.
    REQUIRE authenticated admin OR RETURN 401 or 403. REQUIRE application/json OR RETURN 415.
    BEGIN TRANSACTION; lock record. IF record status is FINAL THEN ROLLBACK; RETURN 409. END IF VALIDATE nonempty partial result under REQ-3-003 OR ROLLBACK; RETURN 400 or 422.
    UPDATE supplied fields only; preserve animal relation; COMMIT; RETURN 200.
    // REQ-3-004. Identical valid payload is idempotent; rollback preserves clinical history.

FUNCTION handleCreateAnimal(request):
    // REQ-3-013; preconditions: JSON request and local persistence available.
    REQUIRE authenticated user or admin OR RETURN 401. REQUIRE application/json OR RETURN 415. VALIDATE REQ-3-001 and REQ-3-002 OR RETURN 400 or 422.
    REQUIRE admin when assigning a different client account OR RETURN 403; unknown supplied client_account_id is 404. BEGIN TRANSACTION; CREATE animal for permitted account; COMMIT; RETURN 201 with Location.
    // Non-idempotent. On any error rollback leaves animals and future clinical relationships unchanged.

FUNCTION handleCreateClinicalRecord(request, animal_id):
    // REQ-3-018; preconditions: JSON request, positive non-deleted animal, and persistence available.
    REQUIRE authenticated admin OR RETURN 401 or 403. REQUIRE application/json OR RETURN 415. RETURN 404 for invalid or absent animal.
    VALIDATE clinical body under REQ-3-001 and REQ-3-003 OR RETURN 400 or 422. BEGIN TRANSACTION; CREATE DRAFT clinical record linked to animal; COMMIT; RETURN 201 with Location.
    // Non-idempotent. Any error rolls back and leaves animal and existing clinical history unchanged.

FUNCTION handleCreateVaccination(request, animal_id):
    // REQ-3-024; preconditions: JSON request, positive non-deleted animal, and persistence available.
    REQUIRE authenticated admin OR RETURN 401 or 403. REQUIRE application/json OR RETURN 415. RETURN 404 for invalid or absent animal. VALIDATE REQ-3-001 and REQ-3-005 body OR RETURN 400 or 422.
    BEGIN TRANSACTION. IF non-void animal, code, administered_on tuple exists THEN ROLLBACK; RETURN 409. END IF CREATE vaccination; COMMIT; RETURN 201 with Location.
    // Non-idempotent. Errors rollback and preserve the animal and all vaccination history.

FUNCTION handleFinalizeClinicalRecord(request, record_id):
    // REQ-3-021; preconditions: JSON request, existing DRAFT record, and persistence available.
    REQUIRE authenticated admin OR RETURN 401 or 403. REQUIRE application/json OR RETURN 415. VALIDATE finalized_at under REQ-3-001 OR RETURN 400 or 422.
    BEGIN TRANSACTION; lock record. IF status is not DRAFT THEN ROLLBACK; RETURN 409. END IF SET status FINAL, finalized_at, and finalized_by caller; COMMIT; RETURN 200.
    // REQ-3-004. Non-idempotent; rollback keeps the draft and all medical relations unchanged.

FUNCTION handleVoidVaccination(request, vaccination_id):
    // REQ-3-026; preconditions: JSON request, existing non-void vaccination, and persistence available.
    REQUIRE authenticated admin OR RETURN 401 or 403. REQUIRE application/json OR RETURN 415. VALIDATE void data under REQ-3-001 and REQ-3-007 OR RETURN 400 or 422.
    BEGIN TRANSACTION; lock vaccination. IF already void or voided_on precedes administered_on THEN ROLLBACK; RETURN 409. END IF RECORD void fields and caller; COMMIT; RETURN 200.
    // REQ-3-006 and REQ-3-007. Non-idempotent; rollback leaves event, status calculations, and animal relation unchanged.
